int main(int, char **) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  Arena::init();
  Arena::reserve(&marble_arena_plan);  // like switchTo()
  marble_physics::loadRom();
  RUN_TEST(test_file_matches_converter);
  RUN_TEST(test_songs_stay_inside);
  RUN_TEST(test_rom_matches_converter);
  RUN_TEST(test_board_silent_after_boot);
  RUN_TEST(test_board_effects_sound);
  RUN_TEST(test_dizzy_until_pair);
  RUN_TEST(test_effect_ends_and_stop);
  RUN_TEST(test_opm_pitch);
  RUN_TEST(test_wav_dump);
  RUN_TEST(test_race_music);
  RUN_TEST(test_unknown_keeps_music);
  RUN_TEST(test_jingle_effect_music);
  RUN_TEST(test_pair);
  RUN_TEST(test_skip_word_drops);
  RUN_TEST(test_queue_overflow_drops);
#endif
  return UNITY_END();
}
